import { fileURLToPath } from 'node:url';
import { migrate as migrateSqlite } from 'drizzle-orm/better-sqlite3/migrator';
import { migrate as migratePostgres } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';
import { dialectOf, type Db } from './client.ts';

/** SQL migrations generated by `pnpm --filter @tooldrop/db db:generate`: one folder per database. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations', import.meta.url));
export const POSTGRES_MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations-pg', import.meta.url));

/** The advisory lock every toolDrop process takes to migrate a Postgres database: any fixed number. */
const MIGRATION_LOCK = 8_620_401_517;

/** Brings the database's tables up to date. */
export async function runMigrations(db: Db): Promise<void> {
  if (dialectOf(db) !== 'postgres') {
    migrateSqlite(db, { migrationsFolder: MIGRATIONS_FOLDER });
    return;
  }
  const migrate = () =>
    migratePostgres(db as unknown as Parameters<typeof migratePostgres>[0], {
      migrationsFolder: POSTGRES_MIGRATIONS_FOLDER,
    });
  // Processes that start at once against one server take turns, so each
  // migration runs once. The lock belongs to one connection, held aside
  // while the migrations run on the others.
  const pool = (db as unknown as { $client?: unknown }).$client;
  if (!(pool instanceof pg.Pool)) return migrate();
  const client = await pool.connect();
  try {
    await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
    await migrate();
  } finally {
    await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]).catch(() => undefined);
    client.release();
  }
}
